<?php
require_once __DIR__.'/includes/bootstrap.php';
require_once __DIR__.'/includes/arqwar-identity.php';
require_once __DIR__.'/includes/avatars.php';
login_required_html();
$msg='';$error='';
$themes=['blue'=>'Azul eléctrico','red'=>'Rojo plasma','green'=>'Verde neón','purple'=>'Púrpura','orange'=>'Naranja solar','cyan'=>'Cian','indigo'=>'Índigo','teal'=>'Teal','gold'=>'Dorado','pink'=>'Magenta','slate'=>'Slate','lime'=>'Lima'];
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  if(!hash_equals(csrf_token(),$_POST['csrf']??''))throw new RuntimeException('Solicitud inválida.');
  $a=$_POST['action']??'';
  if($a==='create_team'){
    $alias=trim($_POST['alias']??'');$desc=trim($_POST['description']??'');$theme=$_POST['theme_key']??'blue';$ids=array_values(array_unique(array_filter(array_map('intval',$_POST['participant_ids']??[]))));
    if(strlen($alias)<2)throw new RuntimeException('Ingresa un alias válido.');
    if(!$ids)throw new RuntimeException('Asigna al menos un participante registrado.');
    db()->beginTransaction();
    exec_sql('INSERT INTO team_profiles(alias,description,theme_key) VALUES(?,?,?)',[$alias,$desc,$theme]);
    $tid=(int)db()->lastInsertId();
    foreach($ids as $pid){$p=row('SELECT * FROM participants WHERE id=? AND is_active=1',[$pid]);if(!$p)continue;exec_sql('INSERT INTO team_members(team_profile_id,participant_id,name,role) VALUES(?,?,?,?)',[$tid,$pid,$p['alias'],$p['specialty']]);}
    db()->commit();header('Location: teams.php?created=1');exit;
  }
  if($a==='add_member'){
    $team=(int)$_POST['team_id'];$pid=(int)$_POST['participant_id'];$p=row('SELECT * FROM participants WHERE id=? AND is_active=1',[$pid]);if(!$p)throw new RuntimeException('Participante inválido.');
    exec_sql('INSERT INTO team_members(team_profile_id,participant_id,name,role) VALUES(?,?,?,?)',[$team,$pid,$p['alias'],$p['specialty']]);header('Location: teams.php?member_added=1');exit;
  }
  if($a==='remove_member'){if(!is_admin())throw new RuntimeException('Solo el administrador puede retirar integrantes de un equipo.');exec_sql('DELETE FROM team_members WHERE id=?',[(int)$_POST['member_id']]);header('Location: teams.php?member_removed=1');exit;}
  if($a==='toggle_team'){if(!is_admin())throw new RuntimeException('Solo el administrador puede activar o desactivar equipos.');exec_sql('UPDATE team_profiles SET is_active=? WHERE id=?',[(int)$_POST['active'],(int)$_POST['team_id']]);header('Location: teams.php?toggled=1');exit;}
 }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$error=$e->getMessage();}
}
if(isset($_GET['created']))$msg='Equipo creado.';elseif(isset($_GET['member_added']))$msg='Participante asignado.';elseif(isset($_GET['member_removed']))$msg='Participante retirado.';elseif(isset($_GET['toggled']))$msg='Estado actualizado.';
$participants=rows('SELECT * FROM participants WHERE is_active=1 ORDER BY alias');
$teams=rows('SELECT tp.*,(SELECT COUNT(*) FROM team_members tm WHERE tm.team_profile_id=tp.id) member_count FROM team_profiles tp ORDER BY tp.is_active DESC,tp.alias');
foreach($teams as &$t){$t['members']=rows('SELECT tm.id,tm.participant_id,COALESCE(p.alias,tm.name) alias,COALESCE(p.specialty,tm.role) specialty,p.avatar_emoji FROM team_members tm LEFT JOIN participants p ON p.id=tm.participant_id WHERE tm.team_profile_id=? ORDER BY alias',[(int)$t['id']]);}
unset($t);
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ARQWAR · Equipos</title><link href="assets/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="assets/css/app.css"><link rel="stylesheet" href="assets/css/arqwar-identity.css?v=20261028-2"><link rel="stylesheet" href="assets/css/avatar-3d.css?v=3">
</head><body class="gm-body arqwar-glow-bg"><nav class="navbar navbar-dark border-bottom border-secondary-subtle"><div class="container-fluid"><?= arqwar_brand_html('EQUIPOS') ?><div class="d-flex gap-2 flex-wrap"><a class="btn btn-sm btn-outline-info" href="<?=is_admin()?'participants.php':'mi-perfil.php'?>"><?=is_admin()?'Participantes':'Mi perfil'?></a><a class="btn btn-sm btn-warning" href="game-master.php?new=1">Crear partida</a><a class="btn btn-sm btn-outline-light" href="index.php">Inicio</a><?php if(is_admin()):?><a class="btn btn-sm btn-danger" href="admin.php?section=teams">Administrar CRUD</a><?php endif;?></div></div></nav><main class="container-fluid py-4 px-lg-4"><div class="row g-4"><div class="col-xl-4"><section class="panel p-4 arq-card depth-card"><div class="eyebrow">PASO 2</div><h1 class="h3">Crear equipo</h1><p class="text-secondary">Primero registra participantes globales. Aquí solo los asignas al equipo.</p><?php if(!$participants):?><div class="alert alert-warning">Aún no tienes participantes. <a href="<?=is_admin()?'participants.php':'mi-perfil.php'?>"><?=is_admin()?'Créalo primero':'Completa tu perfil'?></a>.</div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($msg):?><div class="alert alert-success"><?=e($msg)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create_team"><label class="form-label">Alias del equipo</label><input class="form-control form-control-lg mb-3" name="alias" placeholder="Ej.: Titanes Cloud" required><label class="form-label">Descripción</label><textarea class="form-control mb-3" name="description" rows="2" placeholder="Describe la identidad del equipo"></textarea><label class="form-label">Color / tema</label><div class="theme-palette mb-3"><?php $first=true; foreach($themes as $key=>$label):?><label class="theme-choice theme-<?=$key?>"><input type="radio" name="theme_key" value="<?=$key?>" <?=$first?'checked':''?>><span class="theme-choice-ui"><i></i><b><?=e($label)?></b><small><?=e($key)?></small></span></label><?php $first=false; endforeach;?></div><label class="form-label fw-bold">Participantes</label><div class="participant-check-list"><?php foreach($participants as $p):?><label class="glass-option"><input class="form-check-input" type="checkbox" name="participant_ids[]" value="<?=$p['id']?>"><span class="team-picker-person"><?=arqwar_avatar_html((string)($p['avatar_emoji']?:'cyber_skull'),'team-picker-avatar')?><span><b><?=e($p['alias'])?></b><small><?=e($p['specialty']?:'Participante')?></small></span></span></label><?php endforeach;?></div><button class="btn btn-warning btn-lg w-100 mt-3" <?=$participants?'':'disabled'?>>Crear equipo</button></form></section></div><div class="col-xl-8"><div class="d-flex justify-content-between align-items-center mb-3 flex-wrap gap-3"><div><div class="eyebrow">EQUIPOS PERSISTENTES</div><h2 class="h3 mb-0">Equipos creados</h2></div><a class="btn btn-outline-info" href="<?=is_admin()?'participants.php':'mi-perfil.php'?>"><?=is_admin()?'+ Participante':'Mi perfil'?></a></div><div class="row g-3"><?php foreach($teams as $t):?><div class="col-lg-6"><article class="panel p-3 arq-card depth-card theme-shell theme-<?=e($t['theme_key'])?>"><div class="d-flex justify-content-between align-items-start gap-2"><div><div class="theme-dot theme-<?=e($t['theme_key'])?>"></div><h3 class="h4 mb-1"><?=e($t['alias'])?></h3><p class="text-secondary small mb-1"><?=e($t['description']?:'Sin descripción')?></p><div class="small text-info-emphasis">Tema: <?=e($themes[$t['theme_key']]??$t['theme_key'])?></div></div><span class="badge <?=$t['is_active']?'text-bg-success':'text-bg-secondary'?>"><?=$t['is_active']?'Activo':'Inactivo'?></span></div><div class="team-members-strip mt-3"><div class="d-flex flex-wrap gap-2"><?php foreach($t['members'] as $m):?><span class="member-name-pill glass-chip"><?=arqwar_avatar_html((string)($m['avatar_emoji']?:'cyber_skull'),'team-member-avatar')?><span class="team-member-copy"><b><?=e($m['alias'])?></b><small><?=e($m['specialty']?:'Participante')?></small></span><?php if(is_admin()):?><form method="post" class="d-inline"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="remove_member"><input type="hidden" name="member_id" value="<?=$m['id']?>"><button class="btn btn-link btn-sm text-danger p-0" title="Retirar">×</button></form><?php endif;?></span><?php endforeach;?></div></div><form method="post" class="d-flex gap-2 mt-3"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_member"><input type="hidden" name="team_id" value="<?=$t['id']?>"><select class="form-select form-select-sm" name="participant_id" required><option value="">Agregar participante...</option><?php $used=array_column($t['members'],'participant_id');foreach($participants as $p):if(in_array($p['id'],$used))continue;?><option value="<?=$p['id']?>"><?=e($p['alias'])?></option><?php endforeach;?></select><button class="btn btn-sm btn-outline-info">Asignar</button></form><?php if(is_admin()):?><form method="post" class="mt-2"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle_team"><input type="hidden" name="team_id" value="<?=$t['id']?>"><input type="hidden" name="active" value="<?=$t['is_active']?0:1?>"><button class="btn btn-sm btn-outline-secondary"><?=$t['is_active']?'Desactivar':'Activar'?></button></form><?php endif;?></article></div><?php endforeach;?></div></div></div></main></body></html>